const JOURNEYS=[
 {id:'jerusalem',title:'Jerusalem, a city renamed',icon:'🏛️',blurb:'One hilltop, and the names each ruler gave it.',steps:[
  {y:-1350,c:P('jerusalem'),z:5,t:'<b>Urusalim.</b> A small hill town whose ruler, Abdi-Heba, writes on clay to his overlord in Egypt, asking for archers.'},
  {y:-950,c:P('jerusalem'),z:6,t:'<b>Yerushalayim.</b> The capital of Judah and the site of its Temple. For Jews it has been the centre of the map ever since.'},
  {y:-586,c:P('jerusalem'),z:4,t:'Babylon burns the city and the Temple. The memory of that loss, and of return, becomes scripture.'},
  {y:70,c:P('jerusalem'),z:6,t:'Rome destroys the Second Temple. One retaining wall of Herod’s platform survives: the Western Wall.'},
  {y:136,c:P('jerusalem'),z:6,t:'<b>Aelia Capitolina.</b> Hadrian rebuilds the ruins as a Roman colony named for his own family and closes it to Jews.'},
  {y:335,c:P('jerusalem'),z:7,t:'<b>Hierosolyma.</b> A Christian city of pilgrims, centred on the new Church of the Holy Sepulchre.'},
  {y:692,c:P('jerusalem'),z:7,t:'<b>Bayt al-Maqdis, al-Quds.</b> “The Holy.” The Dome of the Rock rises on the old Temple platform, now the Haram al-Sharif.'},
  {y:1099,c:P('jerusalem'),z:5,t:'Crusaders make it the capital of a Latin kingdom. Eighty-eight years later Saladin takes it back.'},
  {y:1541,c:P('jerusalem'),z:7,t:'Suleiman builds the walls you can walk today. For four centuries it is a provincial Ottoman town, sacred to three faiths.'},
  {y:1949,c:P('jerusalem'),z:7,t:'A ceasefire line cuts the city in two: Israel in the west, Jordan in the east and the Old City.'},
  {y:1967.5,c:P('jerusalem'),z:7,t:'Israel takes the east and declares the city united. Palestinians claim East Jerusalem as their capital. Its status is still unsettled.'}]},
 {id:'name',title:'What do you call this land?',icon:'🏷️',blurb:'Canaan, Israel, Judaea, Palaestina, Filasṭīn… every name has a date.',steps:[
  {y:-1400,c:[35.1,31.9],z:1.6,t:'<b>Canaan</b>, to the people who live here. <b>Retjenu</b>, to the Egyptians who rule them.'},
  {y:-850,c:[35.1,31.9],z:1.8,t:'<b>Israel</b> in the north, <b>Judah</b> in the south, <b>Philistia</b> on the coast. The Philistines’ name will outlast them.'},
  {y:-450,c:[35.2,31.8],z:3,t:'<b>Yehud</b>: a small Persian province around Jerusalem. From it comes the word <i>Yehudi</i> — Jew.'},
  {y:-80,c:[35.2,31.9],z:2,t:'<b>Ioudaia</b>, <b>Judaea</b>: the Greek and Latin for the Hasmonean kingdom at its widest.'},
  {y:135,c:[35.2,31.9],z:2,t:'After the last revolt Rome renames it <b>Syria Palaestina</b>, reviving the old Greek word for the Philistine coast.'},
  {y:700,c:[35.1,31.8],z:2,t:'The Arab conquerors keep the Roman name: <b>Jund Filasṭīn</b>, the district of Palestine. The north is <b>al-Urdunn</b>.'},
  {y:1150,c:[35.2,32.2],z:1.8,t:'To the Crusaders it is <b>Outremer</b>, “beyond the sea”, and the Kingdom of Jerusalem. To Jews it is <b>Eretz Yisrael</b> throughout.'},
  {y:1700,c:[35.2,32.2],z:1.6,t:'Under the Ottomans no province has the name; the land is part of <b>Bilād al-Shām</b>. “Palestine” and “the Holy Land” live on in speech.'},
  {y:1925,c:[35.1,31.8],z:1.8,t:'<b>Palestine</b> becomes official again under Britain — on stamps in English, Arabic and Hebrew, where it reads <b>פלשתינה (א״י)</b>.'},
  {y:1955,c:[35.1,31.8],z:1.8,t:'<b>Israel</b>; and for the lands on the other side of the line, the <b>West Bank</b> and the <b>Gaza Strip</b>.'},
  {y:2026.8,c:[35.1,31.8],z:1.8,t:'Today: <b>Israel</b>, <b>Palestine</b>, the Occupied Territories, Judea and Samaria. Which name you use still says where you stand.'}]},
 {id:'gaza',title:'Gaza, the gate to Egypt',icon:'🐚',blurb:'Four thousand years at the edge of two worlds.',steps:[
  {y:-1400,c:P('gaza'),z:4,t:'Egypt’s headquarters in Canaan: the first town an army reaches after crossing Sinai.'},
  {y:-1000,c:P('gaza'),z:4,t:'The southernmost of the five Philistine cities, and the scene of the Samson story.'},
  {y:-332,c:P('gaza'),z:4,t:'Alexander besieges it for two months. Rebuilt, it becomes a Greek-speaking port.'},
  {y:100,c:[34.9,30.9],z:2.5,t:'The Incense Road ends here. Frankincense from Arabia crosses the Negev to Gaza’s ships.'},
  {y:520,c:P('gaza'),z:4,t:'A famous school of rhetoric, and wine exported across the Byzantine world.'},
  {y:1387,c:P('khanyunis'),z:5,t:'A Mamluk provincial capital on the post road from Cairo to Damascus; Khan Yunis is one of its inns.'},
  {y:1949,c:P('gaza'),z:5,t:'The armistice leaves a strip 40 km long under Egypt. Its population triples with refugees from the towns and villages to the north and east.'},
  {y:1967.5,c:P('gaza'),z:5,t:'Israel occupies the Strip; settlements follow, until the withdrawal of 2005.'},
  {y:2007.5,c:P('gaza'),z:5,t:'Hamas takes over. A blockade closes the gate that Gaza had always been.'},
  {y:2026.8,c:P('gaza'),z:6,t:'After two years of war most of Gaza is rubble. Since the 2025 ceasefire its people live west of the Yellow Line, on less than half the Strip.'}]},
 {id:'power',title:'Ruled from elsewhere',icon:'🧵',blurb:'Follow the gold thread to the capitals that gave the orders.',steps:[
  {y:-1300,cap:1,t:'<b>Thebes</b>, 450 miles up the Nile. Canaan’s kings are vassals who write to Pharaoh on clay.'},
  {y:-560,cap:1,t:'<b>Babylon.</b> Judah’s court is carried there in chains, and writes much of the Bible by its rivers.'},
  {y:-450,cap:1,t:'<b>Persepolis.</b> The Persian Great King lets the exiles go home, and taxes them from more than a thousand miles away.'},
  {y:100,cap:1,t:'<b>Rome.</b> Six to eight weeks by sea and road. Its legions destroy the Temple; its governor sits at Caesarea.'},
  {y:500,cap:1,t:'<b>Constantinople.</b> A Christian emperor pays for the churches that pilgrims cross the world to see.'},
  {y:700,cap:1,t:'<b>Damascus.</b> The nearest capital the land has known; the Umayyads build the Dome of the Rock.'},
  {y:1400,cap:1,t:'<b>Cairo.</b> Mamluk sultans post their letters up the coast by horse relay in ten days.'},
  {y:1700,cap:1,t:'<b>Istanbul.</b> Four centuries of Ottoman rule: the longest unbroken government in the land’s history.'},
  {y:1930,cap:1,t:'<b>London.</b> 2,250 miles away. Britain promises the same land in different words to different people.'},
  {y:1960,c:[35.2,31.8],z:2,t:'After 1948 the thread shortens: Jerusalem, Amman, Cairo. For the first time in two thousand years the land is ruled from inside itself — though not by all who live in it.'}]}
];
